"""GitHub markdown tables built from rows of strings."""


def _line(cells):
    return "| " + " | ".join(cells) + " |"


def to_markdown(rows):
    """Markdown table for rows, where rows[0] is the header. Cells are stripped and "|" is escaped as "\\|"."""
    if not rows:
        raise ValueError("no rows")
    table = [[cell.strip().replace("|", "\\|") for cell in row] for row in rows]
    header = table[0]
    if not header:
        raise ValueError("empty header")
    for i, row in enumerate(table):
        if len(row) != len(header):
            raise ValueError(f"row {i + 1} has {len(row)} cells, header has {len(header)}")
    separator = ["---"] * len(header)
    return "\n".join([_line(header), _line(separator)] + [_line(row) for row in table[1:]])
