import contextlib
import io
import unittest
from unittest import mock

from textkit.cli import main
from textkit.mdtable import to_markdown


def run(*argv, stdin=""):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err), \
            mock.patch("sys.stdin", io.StringIO(stdin)):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class ToMarkdownTest(unittest.TestCase):
    def test_header_separator_and_rows(self):
        self.assertEqual(to_markdown([["a", "b"], ["1", "2"], ["3", "4"]]),
                         "| a | b |\n| --- | --- |\n| 1 | 2 |\n| 3 | 4 |")

    def test_header_only(self):
        self.assertEqual(to_markdown([["a"]]), "| a |\n| --- |")

    def test_cells_are_stripped(self):
        self.assertEqual(to_markdown([[" a ", "\tb"], ["1 ", " 2  "]]),
                         "| a | b |\n| --- | --- |\n| 1 | 2 |")

    def test_pipes_are_escaped(self):
        self.assertEqual(to_markdown([["x|y", "b"], ["a | b", "|"]]),
                         "| x\\|y | b |\n| --- | --- |\n| a \\| b | \\| |")

    def test_no_rows_raises(self):
        with self.assertRaises(ValueError):
            to_markdown([])

    def test_empty_header_raises(self):
        with self.assertRaises(ValueError):
            to_markdown([[]])

    def test_ragged_rows_raise(self):
        with self.assertRaises(ValueError):
            to_markdown([["a", "b"], ["1"]])
        with self.assertRaises(ValueError):
            to_markdown([["a"], ["1", "2"]])


class MdtableCommandTest(unittest.TestCase):
    def test_prints_table_from_stdin(self):
        self.assertEqual(run("mdtable", stdin="a,b\n1,2\n"),
                         (0, "| a | b |\n| --- | --- |\n| 1 | 2 |\n", ""))

    def test_quoted_csv_fields(self):
        _, out, _ = run("mdtable", stdin='name,note\n"Smith, J","say ""hi"""\n')
        self.assertEqual(out, "| name | note |\n| --- | --- |\n| Smith, J | say \"hi\" |\n")

    def test_ragged_csv_exits_2_with_error(self):
        code, out, err = run("mdtable", stdin="a,b\n1\n")
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err.startswith("error: "))

    def test_empty_stdin_exits_2_with_error(self):
        code, out, err = run("mdtable", stdin="")
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err.startswith("error: "))


if __name__ == "__main__":
    unittest.main()
