import contextlib
import io
import unittest

from textkit.cli import main
from textkit.near import closest, levenshtein


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class LevenshteinTest(unittest.TestCase):
    def test_known_distances(self):
        self.assertEqual(levenshtein("kitten", "sitting"), 3)
        self.assertEqual(levenshtein("helo", "hello"), 1)
        self.assertEqual(levenshtein("flaw", "lawn"), 2)

    def test_empty_strings(self):
        self.assertEqual(levenshtein("", ""), 0)
        self.assertEqual(levenshtein("", "abc"), 3)
        self.assertEqual(levenshtein("abc", ""), 3)

    def test_identical_and_symmetric(self):
        self.assertEqual(levenshtein("same", "same"), 0)
        self.assertEqual(levenshtein("abc", "xbcd"), levenshtein("xbcd", "abc"))


class ClosestTest(unittest.TestCase):
    def test_picks_nearest(self):
        self.assertEqual(closest("helo", ["world", "hello", "help"]), "hello")

    def test_ties_go_to_first(self):
        self.assertEqual(closest("cat", ["cab", "car"]), "cab")
        self.assertEqual(closest("cat", ["car", "cab"]), "car")

    def test_within_max_distance_inclusive(self):
        self.assertEqual(closest("abc", ["axy"], max_distance=2), "axy")

    def test_beyond_max_distance_is_none(self):
        self.assertIsNone(closest("zzzz", ["hello"]))
        self.assertIsNone(closest("abc", ["axy"], max_distance=1))

    def test_default_max_distance_is_2(self):
        self.assertEqual(closest("abc", ["axy"]), "axy")
        self.assertIsNone(closest("abcd", ["wxyz"]))

    def test_empty_candidates_is_none(self):
        self.assertIsNone(closest("word", []))

    def test_max_distance_zero_requires_exact(self):
        self.assertEqual(closest("hello", ["hello"], max_distance=0), "hello")
        self.assertIsNone(closest("helo", ["hello"], max_distance=0))

    def test_negative_max_distance_raises(self):
        with self.assertRaises(ValueError):
            closest("helo", ["hello"], max_distance=-1)


class NearCommandTest(unittest.TestCase):
    def test_prints_match(self):
        self.assertEqual(run("near", "helo", "hello", "help"), (0, "hello\n", ""))

    def test_no_match_exits_1(self):
        self.assertEqual(run("near", "zzzz", "hello"), (1, "", "no match\n"))

    def test_max_option(self):
        self.assertEqual(run("near", "helo", "hello", "--max", "0"), (1, "", "no match\n"))
        self.assertEqual(run("near", "helo", "hello", "--max", "1"), (0, "hello\n", ""))

    def test_negative_max_exits_2_with_error(self):
        code, out, err = run("near", "helo", "hello", "--max", "-1")
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err.startswith("error: "))

    def test_json_output(self):
        code, out, _ = run("--json", "near", "helo", "hello")
        self.assertEqual(code, 0)
        self.assertIn('"output": ["hello"]', out)


if __name__ == "__main__":
    unittest.main()

